#define VBIOS_INT_SOFT_KEYBOARD_16(CHUNK) \
    CHUNK("cmp ah, 00                            \njz $(keyboard_16_read)               \ncmp ah, 10                            \njz $(keyboard_16_read)               \ncmp ah, 01                            \njz $(keyboard_16_status)             \ncmp ah, 11                            \njz $(keyboard_16_status)             \ncmp ah, 02                            \njz $(keyboard_16_flags)              \ncmp ah, 05                            \njz $(keyboard_16_store)              \niret                                 \n$(keyboard_16_read):                 \npush bx                              \npush ds                              \nmov ax, 0040                         \nmov ds, ax                           \n$(keyboard_16_wait):                 \nmov bx, ds:[001a]                    \ncmp bx, ds:[001c]                    \njnz $(keyboard_16_read_ready)        \nsti                                  \nhlt                                  \ncli                                  \njmp near $(keyboard_16_wait)         \n$(keyboard_16_read_ready):           \npush ds                              \nxor ax, ax                           \nmov ds, ax                           \nmov ax, ds:[bx]                      \npop ds                               \nadd bx, 0002                         \ncmp bx, 043e                         \njb $(keyboard_16_head_ready)         \nmov bx, 041e                         \n$(keyboard_16_head_ready):           \nmov ds:[001a], bx                    \npop ds                               \npop bx                               \niret                                 \n$(keyboard_16_status):               \npush bx                              \npush ds                              \nmov ax, 0040                         \nmov ds, ax                           \nmov bx, ds:[001a]                    \ncmp bx, ds:[001c]                    \njnz $(keyboard_16_status_ready)      \nmov bx, sp                           \nor word ss:[bx+08], 0040             \njmp near $(keyboard_16_status_done)  \n$(keyboard_16_status_ready):         \npush ds                              \nxor ax, ax                           \nmov ds, ax                           \nmov ax, ds:[bx]                      \npop ds                               \nmov bx, sp                           \nand word ss:[bx+08], ffbf            \n$(keyboard_16_status_done):          \npop ds                               \npop bx                               \niret                                 \n$(keyboard_16_flags):                \npush bx                              \npush ds                              \nmov bx, 0040                         \nmov ds, bx                           \nmov al, ds:[0017]                    \npop ds                               \npop bx                               \niret                                 \n$(keyboard_16_store):                \npush bx                              \npush ds                              \npush si                              \nmov ax, 0040                         \nmov ds, ax                           \nmov bx, ds:[001c]                    \nmov si, bx                           \nadd si, 0002                         \ncmp si, 043e                         \njb $(keyboard_16_store_tail_ready)   \nmov si, 041e                         \n$(keyboard_16_store_tail_ready):     \ncmp si, ds:[001a]                    \njz $(keyboard_16_store_full)         \nmov ax, cx                           \n") \
